Revise the ConcIR candidate for the same requirements. The requirements and the frozen contract are authoritative; the feedback is repair context.

<domain_requirements>
Design a program with two mutexes A and B and two worker threads. Each worker acquires both mutexes, works inside the critical section, releases both, and terminates. Main spawns both workers and joins them. Every interleaving must terminate and both workers must complete.
</domain_requirements>

<contract>
{
  "name": "abba-2lock",
  "properties": [
    {
      "kind": "deadlock_free",
      "id": "no-deadlock"
    }
  ],
  "preserved": [
    {
      "kind": "reachable",
      "description": "main::t1 completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::t1"
      }
    },
    {
      "kind": "reachable",
      "description": "main::t2 completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::t2"
      }
    }
  ],
  "assumptions": {
    "sequential_consistency": true,
    "no_spurious_wakeups": true
  },
  "bounds": {
    "max_threads": 8,
    "max_frames_per_thread": 8,
    "max_states": 20000,
    "max_depth": 64,
    "max_boundary_events": 256
  },
  "allowed_scope": {
    "allow_lock_reorder": true
  }
}
</contract>

